/**
 * Verified nominal forms for the sentence generator.
 *
 * A form is taken from the primary oracle (ashtadhyayi.com śabda tables, generated by vidyut)
 * when the word is a headword there. Otherwise — only for regular a / ā / ī stems — it is
 * built by MODEL: the endings of an oracle paradigm of the same class (देव, वन, लता, नदी) are
 * attached to the new stem and ṇatva is applied; `validateModelDeclension` proves that this
 * procedure reproduces every regular oracle paradigm of that class.
 * Independent cross-check for every form: the hand-entered CC0 ending tables of
 * learnsanskrit.org (after Kale) and, for pronouns, its inflected pronoun table.
 */
import { existsSync, readFileSync } from 'node:fs';
import { devaToSlp1, normalizeDeva, slp1ToDeva } from '../../../src/sanskrit/translit';
import type { Gender, Vacana, Vibhakti } from '../../../src/content/types';
import { key, loadAshShabda, normSlp, oraclePath, PATHS, pausa, type AshShabda } from './oracles';

export type StemClass = 'a' | 'A' | 'I';
const LINGA: Record<Gender, string> = { m: 'P', f: 'S', n: 'N' };
const MODEL: Record<string, { word: string; linga: string }> = {
  'a.m': { word: 'देव', linga: 'P' },
  'a.n': { word: 'वन', linga: 'N' },
  'A.f': { word: 'लता', linga: 'S' },
  'I.f': { word: 'नदी', linga: 'S' },
};

/**
 * ṇatva inside one word (रषाभ्यां नो णः समानपदे 8.4.1, अट्कुप्वाङ्नुम्व्यवायेऽपि 8.4.2, पदान्तस्य न 8.4.37). SLP1.
 * Only n at index ≥ `from` (the case ending) may change. Compound stems whose first member holds
 * the r / ṣ follow 8.4.3 ff. and are NOT covered: model declension is used for simple stems only.
 */
export function natva(s: string, from = 0): string {
  const out = s.split('');
  let armed = false;
  for (let i = 0; i < out.length; i++) {
    const c = out[i] ?? '';
    if ('rfFz'.includes(c)) armed = true;
    else if (c === 'n') {
      const next = out[i + 1] ?? '';
      if (i < from) {
        // an n that belongs to the stem as cited is never touched; like any dental it ends the trigger's reach
        armed = false;
      } else if (armed && next !== '' && 'aAiIuUfFeEoOnmyv'.includes(next)) out[i] = 'R';
      else if (armed && !'aAiIuUfFeEoOnmyv'.includes(next)) armed = false; // n + dental etc. blocks
    } else if (!'aAiIuUfFxXeEoOkKgGNpPbBmyvhM'.includes(c)) armed = false;
  }
  return out.join('');
}

const VOICED_FINAL: Record<string, string> = { d: 't', g: 'k', q: 'w', b: 'p' };
/** Display form of an oracle cell: sandhi doublets (रामाद् / रामात्) reduced to the pausa form; longest first (मम before मे). */
export function displayOf(cell: string[]): string[] {
  const keys = new Set(cell.map(key));
  const kept = cell.filter((f) => {
    const k = key(f);
    const twin = VOICED_FINAL[k.charAt(k.length - 1)];
    return !(twin && keys.has(k.slice(0, -1) + twin));
  });
  return kept.map((f) => normalizeDeva(slp1ToDeva(key(f)))).sort((a, b) => b.length - a.length);
}

export interface NominalSource {
  /** accepted forms, display form first */
  forms: string[];
  verifiedBy: string[];
}

export class Nominals {
  readonly ash: Map<string, AshShabda>;
  private readonly byWord = new Map<string, AshShabda[]>();
  /** learnsanskrit ending table: `${stemType}.${gender}.${case}.${number}` → endings (SLP1, pausa) */
  private readonly endings = new Map<string, Set<string>>();
  /** learnsanskrit pronouns: `${stem}.${gender}.${case}.${number}` → forms */
  private readonly pronouns = new Map<string, Set<string>>();

  constructor() {
    this.ash = loadAshShabda();
    for (const e of this.ash.values()) {
      const arr = this.byWord.get(`${e.word}|${e.linga}`) ?? [];
      arr.push(e);
      this.byWord.set(`${e.word}|${e.linga}`, arr);
    }
    const num = (n: string): string => ({ s: '1', d: '2', p: '3' })[n] ?? '';
    if (existsSync(oraclePath(PATHS.lsEndings))) {
      for (const line of readFileSync(oraclePath(PATHS.lsEndings), 'utf8').split('\n').slice(1)) {
        const [type = '', , ending = '', g = '', c = '', n = ''] = line.split(',');
        if (!type) continue;
        const k = `${type}.${g}.${c}.${num(n.trim())}`;
        let s = this.endings.get(k);
        if (!s) this.endings.set(k, (s = new Set()));
        s.add(normSlp(pausa(ending)));
      }
    }
    if (existsSync(oraclePath(PATHS.lsPronouns))) {
      for (const line of readFileSync(oraclePath(PATHS.lsPronouns), 'utf8').split('\n').slice(1)) {
        const [stem = '', , form = '', g = '', c = '', n = ''] = line.split(',');
        if (!stem) continue;
        const k = `${stem}.${g}.${c}.${num(n.trim())}`;
        let s = this.pronouns.get(k);
        if (!s) this.pronouns.set(k, (s = new Set()));
        s.add(normSlp(pausa(form)));
      }
    }
  }

  private cellOf(e: AshShabda, v: Vibhakti, n: Vacana): string[] {
    return e.cells[(v - 1) * 3 + (n - 1)] ?? [];
  }

  /** Oracle entry for a headword; several homonymous entries are accepted only if they agree in every cell. */
  headword(word: string, gender: Gender): AshShabda | undefined {
    const arr = this.byWord.get(`${word}|${LINGA[gender]}`) ?? [];
    if (arr.length === 0) return undefined;
    const first = arr[0];
    if (!first) return undefined;
    for (const other of arr.slice(1)) if (JSON.stringify(other.cells) !== JSON.stringify(first.cells)) return undefined;
    return first;
  }

  byUrlid(urlid: string): AshShabda {
    const e = this.ash.get(urlid);
    if (!e) throw new Error(`oracle entry ${urlid} missing`);
    return e;
  }

  private model(cls: StemClass, gender: Gender, stemSlp: string, v: Vibhakti, n: Vacana): string[] {
    const m = MODEL[`${cls}.${gender}`];
    if (!m) throw new Error(`no model for ${cls}.${gender}`);
    const me = this.headword(m.word, gender);
    if (!me) throw new Error(`model ${m.word} missing in oracle`);
    const mbase = devaToSlp1(m.word).slice(0, -1);
    const base = stemSlp.slice(0, -1);
    return this.cellOf(me, v, n).map((f) => {
      const k = key(f);
      if (!k.startsWith(mbase)) throw new Error(`model form ${f} does not start with ${mbase}`);
      return natva(base + k.slice(mbase.length), base.length);
    });
  }

  /** The learnsanskrit ending table applied to a stem (independent of the oracle). */
  private byEndingTable(cls: StemClass, gender: Gender, stemSlp: string, v: Vibhakti, n: Vacana): Set<string> {
    const base = stemSlp.slice(0, -1);
    const out = new Set<string>();
    for (const e of this.endings.get(`${cls}.${gender}.${v}.${n}`) ?? []) out.add(natva(base + e, base.length));
    return out;
  }

  /**
   * Forms of a noun / adjective cell. `word` is the prātipadika in Devanagari.
   * Throws when the form cannot be verified.
   */
  decline(word: string, gender: Gender, v: Vibhakti, n: Vacana): NominalSource {
    const stemSlp = devaToSlp1(word);
    const last = stemSlp.charAt(stemSlp.length - 1);
    const cls: StemClass | undefined = last === 'a' ? 'a' : last === 'A' ? 'A' : last === 'I' ? 'I' : undefined;
    const head = this.headword(word, gender);
    const verifiedBy: string[] = [];
    let forms: string[];
    if (head) {
      forms = displayOf(this.cellOf(head, v, n));
      verifiedBy.push('oracle:ashtadhyayi-com(shabda)');
      if (cls && MODEL[`${cls}.${gender}`]) {
        const viaModel = new Set(this.model(cls, gender, stemSlp, v, n));
        if (forms.every((f) => viaModel.has(key(f)))) verifiedBy.push('engine:model-declension');
      }
    } else {
      if (!cls || !MODEL[`${cls}.${gender}`]) throw new Error(`${word} (${gender}) is not an oracle headword and has no regular model`);
      forms = displayOf(this.model(cls, gender, stemSlp, v, n).map((k) => slp1ToDeva(k)));
      verifiedBy.push('engine:model-declension');
    }
    if (forms.length === 0) throw new Error(`${word} ${v}.${n}: empty cell`);
    if (cls) {
      const table = this.byEndingTable(cls, gender, stemSlp, v, n);
      if (table.has(key(forms[0] ?? ''))) verifiedBy.push('table:learnsanskrit-endings');
      else if (!head) throw new Error(`${word} ${v}.${n}: model form ${forms[0]} not confirmed by the independent ending table`);
    }
    return { forms, verifiedBy };
  }

  /** A pronoun cell by oracle urlid; cross-checked with the learnsanskrit pronoun table when it has the stem. */
  pronoun(urlid: string, lsStem: string | null, lsGender: string, v: Vibhakti, n: Vacana): NominalSource {
    const forms = displayOf(this.cellOf(this.byUrlid(urlid), v, n));
    if (forms.length === 0) throw new Error(`${urlid} ${v}.${n}: empty cell`);
    const verifiedBy = ['oracle:ashtadhyayi-com(shabda)'];
    if (lsStem) {
      const set = this.pronouns.get(`${lsStem}.${lsGender}.${v}.${n}`);
      if (set?.has(key(forms[0] ?? ''))) verifiedBy.push('table:learnsanskrit-pronouns');
      else throw new Error(`${urlid} ${v}.${n}: ${forms[0]} not in the independent pronoun table`);
    }
    return { forms, verifiedBy };
  }

  /**
   * Proof obligation for model declension: for every regular oracle headword of the class the
   * model must reproduce the oracle cell exactly. Returns [paradigms checked, mismatching paradigms].
   */
  validateModelDeclension(cls: StemClass, gender: Gender): { checked: number; mismatches: string[] } {
    const mismatches: string[] = [];
    let checked = 0;
    const lastChar = cls === 'a' ? null : cls === 'A' ? 'ा' : 'ी';
    for (const e of this.ash.values()) {
      if (e.linga !== LINGA[gender]) continue;
      const w = e.word;
      if (cls === 'a' ? !/[क-ह]$/u.test(w) : !w.endsWith(lastChar ?? '')) continue;
      checked++;
      const stemSlp = devaToSlp1(w);
      let ok = true;
      for (let v = 1; v <= 7 && ok; v++) {
        for (let n = 1; n <= 3 && ok; n++) {
          const want = new Set(this.cellOf(e, v as Vibhakti, n as Vacana).map(key));
          if (want.size === 0) continue;
          const got = this.model(cls, gender, stemSlp, v as Vibhakti, n as Vacana);
          if (!got.every((g) => want.has(g)) || got.length === 0) ok = false;
        }
      }
      if (!ok) mismatches.push(w);
    }
    return { checked, mismatches };
  }
}
